{"command": "cd docs/prototypes && python3 - <<'PY'
import html.parser, re, sys

class P(html.parser.HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.out=[]; self.skip=0; self.cur=[]
    def handle_starttag(self, tag, attrs):
        d=dict(attrs)
        if tag in ('style','script','svg'): self.skip+=1
        if self.skip: return
        if tag in ('section','div','article','header','footer','nav','tr','li','p','h1','h2','h3','h4','h5','label','button','dt','dd','th','td','option','summary'):
            if self.cur: self.out.append(' '.join(''.join(self.cur).split())); self.cur=[]
            ident=d.get('id'); cls=d.get('class','')
            meta=[]
            if ident: meta.append('#'+ident)
            if cls: meta.append('.'+'.'.join(cls.split()[:3]))
            if tag in ('h1','h2','h3','h4') or ident or tag in ('button','label','th'):
                self.out.append(f"[{tag}{''.join(meta)}]")
    def handle_endtag(self, tag):
        if tag in ('style','script','svg'):
            if self.skip: self.skip-=1
            return
        if self.skip: return
        if tag in ('section','div','article','header','footer','nav','tr','li','p','h1','h2','h3','h4','h5','label','button','dt','dd','th','td','option','summary'):
            if self.cur: self.out.append(' '.join(''.join(self.cur).split())); self.cur=[]
    def handle_data(self, data):
        if self.skip: return
        if data.strip(): self.cur.append(data)

for f in ['ui-v7.html','ui-v7-pages.html','ui-v8-admin.html']:
    p=P(); p.feed(open(f,encoding='utf-8').read())
    if p.cur: p.out.append(' '.join(''.join(p.cur).split()))
    lines=[l for l in p.out if l.strip()]
    open('/tmp/'+f.replace('.html','.txt'),'w',encoding='utf-8').write('\n'.join(lines))
    print(f, len(lines))
