function escWf(value) {
  return String(value).replace(/[&<>"']/g, function (ch) {
    return ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[ch];
  });
}

function stepTypeLabel(type) {
  return STEP_CATALOG[type] ? STEP_CATALOG[type].label : type;
}

function workflowStepsHTML(wf) {
  return wf.steps.map(function (step, index) {
    return '<span class="wf-step step-' + step.type + '">' +
      '<span class="wf-step-num">' + String(index + 1).padStart(2, '0') + '</span>' +
      '<span class="wf-step-type">' + stepTypeLabel(step.type) + '</span>' +
      '<span class="wf-step-name">' + escWf(step.name) + '</span>' +
      (step.approval ? '<span class="wf-step-approval">审批</span>' : '') +
    '</span>' + (index < wf.steps.length - 1 ? '<span class="wf-link"></span>' : '');
  }).join('');
}

function workflowUseHref(wf) {
  return 'ui-v7.html#workflow=' + encodeURIComponent(wf.id) +
    '&name=' + encodeURIComponent(wf.name) +
    '&steps=' + encodeURIComponent(wf.steps.map(function (step) { return step.name; }).join('|'));
}

var workflowList = document.getElementById('workflowList');
var workflowEmpty = document.getElementById('workflowEmpty');
var wfStatTotal = document.getElementById('wfStatTotal');
var wfStatEnabled = document.getElementById('wfStatEnabled');
var wfStatDraft = document.getElementById('wfStatDraft');
var wfStatSteps = document.getElementById('wfStatSteps');

function findWorkflow(id) {
  return WORKFLOWS.filter(function (wf) { return wf.id === id; })[0] || null;
}

function renderWorkflows() {
  workflowList.innerHTML = WORKFLOWS.map(function (wf) {
    var a2aCount = wf.steps.filter(function (step) { return step.type === 'a2a'; }).length;
    var approvalCount = wf.steps.filter(function (step) { return step.type === 'approval' || step.approval; }).length;
    var useAction = wf.enabled
      ? '<a class="btn btn-primary btn-sm" href="' + workflowUseHref(wf) + '">在对话中使用</a>'
      : '<button class="btn btn-primary btn-sm" disabled>草稿不可用</button>';
    return '<article class="wf-card' + (wf.enabled ? '' : ' is-draft') + '" data-wf-id="' + escWf(wf.id) + '">' +
      '<div class="wf-head">' +
        '<span class="wf-mark"><svg class="ic" aria-hidden="true"><use href="#i-workflow"/></svg></span>' +
        '<div class="wf-title-wrap">' +
          '<div class="wf-name">' + escWf(wf.name) + ' <span class="tag">' + escWf(wf.version) + '</span></div>' +
          '<p class="wf-desc">' + escWf(wf.desc) + '</p>' +
        '</div>' +
        '<div class="wf-state">' +
          '<button class="wf-switch' + (wf.enabled ? ' is-on' : '') + '" data-wf-toggle role="switch" aria-checked="' + String(wf.enabled) + '" aria-label="' + (wf.enabled ? '停用' : '启用') + escWf(wf.name) + '"><span></span></button>' +
          '<span class="wf-state-text">' + (wf.enabled ? '启用' : '草稿') + '</span>' +
        '</div>' +
      '</div>' +
      '<div class="wf-route"><div class="wf-route-label">执行轨迹</div><div class="wf-steps">' + workflowStepsHTML(wf) + '</div></div>' +
      '<div class="wf-meta"><span>' + wf.steps.length + ' 步</span><span>·</span><span>' + a2aCount + ' 个远程智能体</span><span>·</span><span>' + approvalCount + ' 个审批</span><span>·</span><span>运行 ' + wf.runs + ' 次</span><span class="spacer"></span><span>更新于 ' + escWf(wf.updated) + '</span></div>' +
      '<div class="wf-actions">' + useAction +
        '<button class="btn btn-outline btn-sm" data-wf-edit>编辑</button>' +
        '<button class="btn btn-ghost btn-sm" data-wf-copy>复制</button>' +
        '<span class="spacer"></span>' +
        '<button class="btn btn-ghost btn-sm is-danger-text" data-wf-delete>删除</button>' +
      '</div>' +
    '</article>';
  }).join('');

  workflowEmpty.hidden = WORKFLOWS.length > 0;
  var enabledCount = WORKFLOWS.filter(function (wf) { return wf.enabled; }).length;
  var totalSteps = WORKFLOWS.reduce(function (sum, wf) { return sum + wf.steps.length; }, 0);
  wfStatTotal.textContent = String(WORKFLOWS.length);
  wfStatEnabled.textContent = String(enabledCount);
  wfStatDraft.textContent = String(WORKFLOWS.length - enabledCount);
  wfStatSteps.textContent = String(WORKFLOWS.length ? Math.round(totalSteps / WORKFLOWS.length) : 0);
}

workflowList.addEventListener('click', function (event) {
  var card = event.target.closest('.wf-card');
  if (!card) return;
  var id = card.getAttribute('data-wf-id');
  var wf = findWorkflow(id);
  if (!wf) return;
  if (event.target.closest('[data-wf-toggle]')) {
    wf.enabled = !wf.enabled;
    renderWorkflows();
    showToast(wf.enabled ? '已启用「' + wf.name + '」' : '已停用「' + wf.name + '」');
    return;
  }
  if (event.target.closest('[data-wf-edit]')) {
    openWorkflowEditor(id);
    return;
  }
  if (event.target.closest('[data-wf-copy]')) {
    var copy = JSON.parse(JSON.stringify(wf));
