import re, os, json, glob
files=glob.glob('docs/handoff/*.md')
bad_links=[]
for f in files:
    base=os.path.dirname(f); text=open(f,encoding='utf-8').read()
    for m in re.finditer(r'\[[^\]]*\]\(([^)]+)\)', text):
        url=m.group(1).split('#')[0]
        if not url or url.startswith(('http://','https://','mailto:')): continue
        path=os.path.normpath(os.path.join(base,url))
        if not os.path.exists(path): bad_links.append((f,url))
print('bad links:',bad_links)
bad_json=[]; count=0
for f in files:
    text=open(f,encoding='utf-8').read()
    for i,m in enumerate(re.finditer(r'```json\n(.*?)\n```', text, re.S)):
        count+=1
        try: json.loads(m.group(1))
        except Exception as e: bad_json.append((f,i+1,str(e)))
print('json:',count,'bad:',bad_json)
text=open('docs/handoff/fixtures.md',encoding='utf-8').read()
bad=[]; n=0
for m in re.finditer(r'^data: (\{.*\})$', text, re.M):
    n+=1
    try: json.loads(m.group(1))
    except Exception as e: bad.append((n,str(e)))
print('sse:',n,'bad:',bad)
for f in files:
    lines=open(f,encoding='utf-8').read().splitlines(); bad=[]; i=0
    while i<len(lines):
        if lines[i].startswith('|') and i+1<len(lines) and re.match(r'^\|[\s:|-]+\|$', lines[i+1]):
            n=len(lines[i].split('|'))-2; j=i+2
            while j<len(lines) and lines[j].startswith('|'):
                c=len(lines[j].split('|'))-2
                if c!=n: bad.append((j+1,n,c))
                j+=1
            i=j
        else: i+=1
    print(os.path.basename(f),'table mismatch:',bad[:5])
