var resultScrim = document.getElementById('resultScrim');
var resultDrawer = document.getElementById('resultDrawer');
var resultSub = document.getElementById('resultSub');
var resultBody = document.getElementById('resultBody');
var copyResult = document.getElementById('copyResult');
var resultJsonText = '';
var currentResultKey = null;

function openResultDrawer(key) {
  var data = RESULT_DATA[key];
  if (!data) return;
  currentResultKey = key;
  resultSub.textContent = data.sub;
  resultBody.innerHTML = data.html;
  resultJsonText = JSON.stringify(data.json, null, 2);
  var pre = document.getElementById('resultJson');
  if (pre) pre.textContent = resultJsonText;
  resultScrim.classList.add('is-open');
  resultDrawer.classList.add('is-open');
  resultDrawer.setAttribute('aria-hidden', 'false');
  resultBody.scrollTop = 0;
  resultDrawer.focus();
}

function closeResultDrawer() {
  resultScrim.classList.remove('is-open');
  resultDrawer.classList.remove('is-open');
  resultDrawer.setAttribute('aria-hidden', 'true');
  currentResultKey = null;
}

document.querySelectorAll('[data-open-result]').forEach(function (btn) {
  btn.addEventListener('click', function () {
    openResultDrawer(btn.getAttribute('data-open-result'));
  });
});

var closeResultBtn = document.getElementById('closeResult');
if (closeResultBtn) closeResultBtn.addEventListener('click', closeResultDrawer);
if (resultScrim) resultScrim.addEventListener('click', closeResultDrawer);

if (copyResult) {
  copyResult.addEventListener('click', function () {
    if (!resultJsonText) return;
    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(resultJsonText).then(function () {
        showToast('已复制任务结果 JSON');
      }).catch(function () { fallbackCopy(resultJsonText); });
    } else {
      fallbackCopy(resultJsonText);
    }
  });
}

document.addEventListener('keydown', function (event) {
  if (event.key === 'Escape') closeResultDrawer();
});

